package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os/exec"
	"strings"
	"time"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

type Message struct {
	Type    string `json:"type"`
	Payload string `json:"payload"`
}

type ExprEngine struct {
	variables map[string]string
}

func NewExprEngine() *ExprEngine {
	return &ExprEngine{
		variables: map[string]string{
			"user.name":    "anonymous",
			"user.role":    "viewer",
			"system.time":  time.Now().Format(time.RFC3339),
			"system.version": "2.4.1",
		},
	}
}

// EvaluateExpression processes template expressions like ${variable}
// and supports advanced expressions with pipe operators
func (e *ExprEngine) EvaluateExpression(expr string) (string, error) {
	result := expr

	// Handle simple variable substitution ${var}
	for key, val := range e.variables {
		placeholder := fmt.Sprintf("${%s}", key)
		result = strings.ReplaceAll(result, placeholder, val)
	}

	// Handle pipe expressions: ${expr|command}
	// Used for formatting: ${system.time|date}, ${user.name|upper}
	if strings.Contains(result, "|") {
		parts := strings.SplitN(result, "|", 2)
		if len(parts) == 2 {
			inputVal := strings.TrimSpace(parts[0])
			pipeCmd := strings.TrimSpace(parts[1])

			// Execute pipe transformation
			ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
			defer cancel()

			cmd := exec.CommandContext(ctx, "sh", "-c", fmt.Sprintf("echo '%s' | %s", inputVal, pipeCmd))
			output, err := cmd.Output()
			if err != nil {
				return "", fmt.Errorf("pipe evaluation failed: %w", err)
			}
			result = strings.TrimSpace(string(output))
		}
	}

	return result, nil
}

func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	engine := NewExprEngine()

	for {
		_, msgBytes, err := conn.ReadMessage()
		if err != nil {
			log.Printf("read error: %v", err)
			break
		}

		var msg Message
		if err := json.Unmarshal(msgBytes, &msg); err != nil {
			conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"invalid json"}`))
			continue
		}

		switch msg.Type {
		case "subscribe":
			// Evaluate subscription filter expressions
			result, err := engine.EvaluateExpression(msg.Payload)
			if err != nil {
				response := fmt.Sprintf(`{"error":"%s"}`, err.Error())
				conn.WriteMessage(websocket.TextMessage, []byte(response))
				continue
			}
			response := fmt.Sprintf(`{"type":"subscribed","filter":"%s"}`, result)
			conn.WriteMessage(websocket.TextMessage, []byte(response))

		case "query":
			// Evaluate query expressions for real-time data
			result, err := engine.EvaluateExpression(msg.Payload)
			if err != nil {
				response := fmt.Sprintf(`{"error":"%s"}`, err.Error())
				conn.WriteMessage(websocket.TextMessage, []byte(response))
				continue
			}
			response := fmt.Sprintf(`{"type":"result","data":"%s"}`, result)
			conn.WriteMessage(websocket.TextMessage, []byte(response))

		default:
			conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"unknown type"}`))
		}
	}
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"healthy"}`))
}

func main() {
	http.HandleFunc("/ws", handleWebSocket)
	http.HandleFunc("/health", healthCheck)

	log.Println("WebSocket service starting on :8080")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatalf("server failed: %v", err)
	}
}
